import { useState, useEffect, useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, Typography, Stack, Button, Tooltip, IconButton, Chip, Dialog, DialogTitle, DialogContent, DialogActions } from '@mui/material';
import { useColorScheme } from '@mui/material/styles';
import { IconPlus, IconCalendarEvent, IconRefresh, IconGitBranch } from '@tabler/icons-react';
import axios from 'utils/axios';
import MainCard from 'ui-component/cards/MainCard';
import { useDispatch, useSelector } from 'react-redux';
import { setFilterConfig } from 'store/slices/search';
import { openSnackbar } from 'store/slices/snackbar';
import ConfirmDeleteDialog from 'ui-component/ConfirmDeleteDialog';
import useKeyboardShortcuts, { shortcutTooltip } from 'hooks/useKeyboardShortcuts';
import { BOSDataTable, btnNew, getStatusChipSx, BOSTableToolbar, getCommonDateFilters, matchCommonDateFilters } from 'ui-component/bos';
import { API_PATHS } from 'utils/api-constants';
import usePagePermissions, { PAGE_CODES } from 'hooks/usePagePermissions';
import { isMobile } from 'react-device-detect';

const formatTime12h = (time24) => {
  if (!time24) return '-';
  const [hours, minutes] = time24.split(':');
  const h = parseInt(hours, 10);
  const ampm = h >= 12 ? 'PM' : 'AM';
  const h12 = h % 12 || 12;
  return `${String(h12).padStart(2, '0')}:${minutes} ${ampm}`;
};

const columns = [
  { id: 'index', label: '#', minWidth: 50, align: 'center' },
  { id: 'scheduleNo', label: 'Schedule No', minWidth: 150, bold: true, align: 'center' },
  { id: 'revSourceScheduleNo', label: 'Amendment Schedule No', minWidth: 160, align: 'center' },
  { id: 'scheduleDate', label: 'Schedule Date', minWidth: 110, align: 'center' },
  { id: 'meetingTypeName', label: 'Meeting Type', minWidth: 140, align: 'center' },
  { id: 'meetingDateTime', label: 'Meeting Date/Time', minWidth: 160, align: 'center' },
  { id: 'departmentNames', label: 'Department', minWidth: 160, align: 'center' },
  { id: 'chairedByName', label: 'Chaired By', minWidth: 130, align: 'center' },
  { id: 'hostByName', label: 'Host By', minWidth: 130, align: 'center' },
  { id: 'participantsBy', label: 'Participants By', minWidth: 200, align: 'center' },
  { id: 'createdUser', label: 'CREATED USER', minWidth: 110, align: 'center' },
  { id: 'createdAt', label: 'CREATED DATE', minWidth: 140, align: 'center' },
  { id: 'updatedUser', label: 'UPDATED USER', minWidth: 110, align: 'center' },
  { id: 'updatedAt', label: 'UPDATED DATE', minWidth: 140, align: 'center' },
  { id: 'review', label: 'Review', minWidth: 80, align: 'center' },
  { id: 'status', label: 'Status', minWidth: 100, align: 'center' }
];

export default function MeetingScheduleList() {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const { colorScheme } = useColorScheme();
  const isDark = colorScheme === 'dark';
  const globalQuery = useSelector((state) => state.search.query);
  const globalFilters = useSelector((state) => state.search.filters);
  const perms = usePagePermissions(PAGE_CODES.QMS_MEETING_SCHEDULE);

  const [rows, setRows] = useState([]);
  const [page, setPage] = useState(0);
  const [size, setSize] = useState(10);
  const [loading, setLoading] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState(null);
  const [amendDialogOpen, setAmendDialogOpen] = useState(false);
  const [selectedForAmend, setSelectedForAmend] = useState(null);

  // ── RESOLVED ROWS (SOP #16 Standard) ──
  const resolvedRows = useMemo(() => {
    if (!Array.isArray(rows)) return [];
    return rows.map(row => {
      const d = row.meetingDate || '';
      const t = row.startTime || '';
      const formattedDate = d ? d.split('-').reverse().join('/') : '-';
      
      return {
        ...row,
        scheduleDate: row.createdAt ? row.createdAt.split('T')[0].split('-').reverse().join('/') : '-',
        meetingTypeName: row.meetingType?.meetingName || '-',
        meetingDateTime: d ? `${formattedDate} ${formatTime12h(t)}` : '-',
        departmentNames: (row.departments || []).map(d => d.department?.departmentName).filter(Boolean).join(','),
        chairedByName: row.chairedBy?.employeeName || '-',
        hostByName: row.hostBy?.employeeName || '-',
        participantsBy: (row.participants || []).map(pr => {
          const e = pr.employee;
          return e ? e.employeeName : '';
        }).filter(Boolean).join(', '),
        createdUser: row.createdUser || row.createdBy || '-',
        updatedUser: row.updatedUser || row.updatedBy || '-',
        createdAtRaw: row.createdAt || row.createdDate || null,
        updatedAtRaw: row.updatedAt || row.updatedDate || null,
        createdAt: row.createdAt ? new Date(row.createdAt).toLocaleString('en-GB') : (row.createdDate ? new Date(row.createdDate).toLocaleString('en-GB') : '-'),
        updatedAt: row.updatedAt ? new Date(row.updatedAt).toLocaleString('en-GB') : (row.updatedDate ? new Date(row.updatedDate).toLocaleString('en-GB') : '-'),
        status: row.status || 'OPEN'
      };
    });
  }, [rows]);

  // ── FILTERED ROWS ──
  const filteredRows = useMemo(() => {
    return resolvedRows.filter((row) => {
      if (!matchCommonDateFilters(row, globalFilters, 'createdDate', 'updatedDate')) return false;

      const statusFilter = globalFilters?.status || 'OPEN';
      if (statusFilter !== 'ALL' && row.status !== statusFilter) return false;

      if (globalQuery) {
        const q = globalQuery.toLowerCase();
        return (row.scheduleNo || '').toLowerCase().includes(q) ||
               (row.meetingTypeName || '').toLowerCase().includes(q) ||
               (row.departmentNames || '').toLowerCase().includes(q) ||
               (row.participantsBy || '').toLowerCase().includes(q);
      }
      return true;
    });
  }, [resolvedRows, globalQuery, globalFilters]);

  // ── GLOBAL FILTER CONFIG ──
  useEffect(() => {
    dispatch(setFilterConfig([{
        id: 'dateType', label: 'Date Type', type: 'select', isStarred: true,
        options: [
          { value: 'meetingDate', label: 'Meeting Date' },
          { value: 'createdAt', label: 'Created Date' }
        ],
        defaultValue: 'meetingDate'
      },
      { id: 'fromDate', label: 'From Date', type: 'date', isStarred: true },
      { id: 'toDate', label: 'To Date', type: 'date', isStarred: true },
      {
        id: 'considerDate', label: 'Consider Date?', type: 'select', isStarred: true,
        options: [{ value: 'YES', label: 'Yes' }, { value: 'NO', label: 'No' }],
        defaultValue: 'NO'
      },
      {
        id: 'status', label: 'Status', type: 'select', isStarred: true,
        options: [
          { value: 'ALL', label: 'All' },
          { value: 'OPEN', label: 'Open' },
          { value: 'RESCHEDULE', label: 'Reschedule' },
          { value: 'CLOSED', label: 'Closed' },
          { value: 'AUTO CLOSED', label: 'Auto Closed' },
          { value: 'CANCELLED', label: 'Cancelled' }
        ],
        defaultValue: 'OPEN'
      },
      ...getCommonDateFilters('createdDate', 'updatedDate')]));
    return () => dispatch(setFilterConfig(null));
  }, [dispatch]);

  // ── FETCH ──
  const fetchData = useCallback(async () => {
    setLoading(true);
    try {
      const response = await axios.get(API_PATHS.QMS.MEETING_SCHEDULES);
      const data = Array.isArray(response.data) ? response.data : [];
      setRows(data.sort((a, b) => b.id - a.id));
    } catch (error) {
      console.error('Failed to fetch schedules:', error);
      setRows([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchData(); }, [fetchData]);

  // ── HANDLERS ──
  const handleAdd = () => {
    if (!perms.write) return;
    navigate('/qms/meeting-schedule/create');
  };
  const handleEdit = (item) => { 
    navigate(`/qms/meeting-schedule/edit/${item.id}`); 
  };
  const handleDeleteClick = (row) => { setDeleteTarget(row); setDeleteDialogOpen(true); };

  const handleAmendmentClick = (row) => {
    setSelectedForAmend(row);
    setAmendDialogOpen(true);
  };

  const handleAmendConfirm = async () => {
    setAmendDialogOpen(false);
    try {
      const amended = {
        ...selectedForAmend,
        id: undefined,
        revSourceScheduleNo: selectedForAmend.scheduleNo,
        revNo: (selectedForAmend.revNo || 0) + 1,
        status: 'OPEN',
        createdAt: undefined,
        updatedAt: undefined
      };
      await axios.post(API_PATHS.QMS.MEETING_SCHEDULES, amended);
      dispatch(openSnackbar({ open: true, message: 'Amendment created successfully!', variant: 'alert', severity: 'success' }));
      fetchData();
    } catch (error) {
      dispatch(openSnackbar({ open: true, message: 'Failed to create amendment', variant: 'alert', severity: 'error' }));
    }
  };



  const handleDeleteConfirm = async () => {
    setDeleteDialogOpen(false);
    try {
      await axios.delete(`${API_PATHS.QMS.MEETING_SCHEDULES}/${deleteTarget.id}`);
      dispatch(openSnackbar({ open: true, message: 'Schedule deleted!', variant: 'alert', severity: 'success' }));
      fetchData();
    } catch (error) {
      dispatch(openSnackbar({ open: true, message: 'Failed to delete schedule', variant: 'alert', severity: 'error' }));
    }
  };

  useKeyboardShortcuts({ 'ctrl+n': handleAdd });


  // ── RENDER CELL ──
  const renderCell = (col, row, idx) => {
    let val;
    if (col.id === 'status') {
      const s = row.status || 'OPEN';
      let chipStatus = 'ACTIVE';
      if (s === 'CLOSED' || s === 'AUTO CLOSED') chipStatus = 'INACTIVE';
      if (s === 'RESCHEDULE') chipStatus = 'PENDING';
      if (s === 'CANCELLED') chipStatus = 'INACTIVE';
      val = (
        <Chip 
          label={s} 
          size="small" 
          sx={{
            ...getStatusChipSx(chipStatus),
            fontWeight: 850,
            borderRadius: '6px',
            textTransform: 'uppercase'
          }} 
        />
      );
    } else if (col.id === 'createdAt' || col.id === 'updatedAt') {
      const rawDateVal = col.id === 'createdAt' ? row.createdAtRaw : row.updatedAtRaw;
      if (!rawDateVal) {
        val = <Typography variant="body2" color="text.secondary">-</Typography>;
      } else {
        const dt = new Date(rawDateVal);
        if (isNaN(dt.getTime())) {
          val = <Typography variant="body2" color="text.secondary">-</Typography>;
        } else {
          // Format date as DD/MM/YYYY
          const day = String(dt.getDate()).padStart(2, '0');
          const month = String(dt.getMonth() + 1).padStart(2, '0');
          const year = dt.getFullYear();
          const d = `${day}/${month}/${year}`;
          
          // Format time as 12-hour style (e.g., 10:53 PM)
          const t = dt.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', hour12: true });
          
          val = (
            <Box>
              <Typography variant="body2" sx={{ fontWeight: 600, color: 'text.primary' }}>
                {d}
              </Typography>
              <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.1 }}>
                {t}
              </Typography>
            </Box>
          );
        }
      }
    } else if (col.id === 'index') {
      val = (
        <Typography variant="body2" color="text.secondary" align="center" sx={{ fontWeight: 600 }}>
          {idx + 1 + page * size}
        </Typography>
      );
    } else if (col.id === 'scheduleNo') {
      val = (
        <Typography variant="body2" sx={{ fontWeight: 800, color: 'primary.main', letterSpacing: '0.3px' }}>
          {row.scheduleNo || '-'}
        </Typography>
      );
    } else if (col.id === 'revSourceScheduleNo') {
      val = row.revSourceScheduleNo ? (
        <Chip 
          label={row.revSourceScheduleNo} 
          size="small" 
          variant="outlined" 
          color="warning" 
          sx={{ borderRadius: '6px', fontWeight: 700, height: '22px' }} 
        />
      ) : (
        <Typography variant="body2" color="text.secondary">-</Typography>
      );
    } else if (col.id === 'scheduleDate') {
      val = (
        <Typography variant="body2" sx={{ fontWeight: 500, color: 'text.primary' }}>
          {row.scheduleDate || '-'}
        </Typography>
      );
    } else if (col.id === 'meetingTypeName') {
      val = (
        <Typography variant="body2" sx={{ fontWeight: 700, color: 'text.primary' }}>
          {row.meetingTypeName || '-'}
        </Typography>
      );
    } else if (col.id === 'meetingDateTime') {
      if (row.meetingDate) {
        const d = row.meetingDate.split('-').reverse().join('/');
        const t = formatTime12h(row.startTime);
        val = (
          <Box>
            <Typography variant="body2" sx={{ fontWeight: 600, color: 'text.primary' }}>
              {d}
            </Typography>
            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.1 }}>
              {t}
            </Typography>
          </Box>
        );
      } else {
        val = <Typography variant="body2" color="text.secondary">-</Typography>;
      }
    } else if (col.id === 'departmentNames') {
      const fullDepts = row.departmentNames || '-';
      const truncated = fullDepts.length > 30 ? `${fullDepts.substring(0, 30)}...` : fullDepts;
      val = (
        <Typography variant="body2" sx={{ color: 'text.primary', fontWeight: 500 }}>
          {truncated}
        </Typography>
      );
    } else if (col.id === 'chairedByName' || col.id === 'hostByName') {
      const name = col.id === 'chairedByName' ? row.chairedByName : row.hostByName;
      val = (
        <Typography variant="body2" sx={{ fontWeight: 500, color: 'text.primary' }}>
          {name}
        </Typography>
      );
    } else if (col.id === 'participantsBy') {
      const fullParts = row.participantsBy || '-';
      const truncated = fullParts.length > 35 ? `${fullParts.substring(0, 35)}...` : fullParts;
      val = (
        <Typography variant="body2" color="text.secondary">
          {truncated}
        </Typography>
      );
    } else if (col.id === 'review') {
      const r = row.review || 'NO';
      val = (
        <Chip 
          label={r} 
          size="small" 
          variant="outlined" 
          sx={{ 
            borderRadius: '6px', 
            height: '22px', 
            fontWeight: 700, 
            color: r === 'YES' ? 'primary.main' : 'text.secondary', 
            borderColor: r === 'YES' ? 'primary.light' : 'divider',
            bgcolor: r === 'YES' ? 'primary.lighter' : 'transparent'
          }} 
        />
      );
    } else if (col.id === 'createdUser') {
      val = (
        <Typography variant="body2" sx={{ fontWeight: 600, color: 'text.primary' }}>
          {(row.createdUser || row.createdBy) || '-'}
        </Typography>
      );
    } else if (col.id === 'updatedUser') {
      val = (
        <Typography variant="body2" sx={{ fontWeight: 600, color: 'text.primary' }}>
          {(row.updatedUser || row.updatedBy) || '-'}
        </Typography>
      );
    } else {
      let rawVal = row[col.id];
      if (rawVal === undefined || rawVal === null) {
        const snakeCaseId = col.id.replace(/[A-Z]/g, letter => `_${letter.toLowerCase()}`);
        rawVal = row[snakeCaseId];
      }
      if (typeof rawVal === 'boolean') {
        val = rawVal ? 'Yes' : 'No';
      } else if (typeof rawVal === 'object' && rawVal !== null) {
        val = rawVal.name || rawVal.label || rawVal.id || '-';
      } else {
        val = (rawVal !== null && rawVal !== undefined && rawVal !== '') ? String(rawVal) : '-';
      }
    }

    const tooltipHint = isMobile ? 'Double-tap to edit' : 'Double-click to edit';
    let finalTooltip = tooltipHint;
    if (col.id === 'departmentNames' && row.departmentNames && row.departmentNames.length > 30) {
      finalTooltip = `${row.departmentNames} | ${tooltipHint}`;
    } else if (col.id === 'participantsBy' && row.participantsBy && row.participantsBy.length > 35) {
      finalTooltip = `${row.participantsBy} | ${tooltipHint}`;
    }

    return (
      <Tooltip title={finalTooltip} placement="top" followCursor enterDelay={200}>
        <div style={{ width: '100%', display: 'flex', justifyContent: col.align === 'center' ? 'center' : 'flex-start' }}>
          {val}
        </div>
      </Tooltip>
    );
  };

  return (
    <MainCard fullWidth
      title={
        <Stack direction="row" alignItems="center" spacing={1.5} sx={{ py: 0.5 }}>
          <Box sx={{ p: 1, bgcolor: 'primary.light', borderRadius: 2, display: 'flex' }}>
            <IconCalendarEvent size={22} color={isDark ? '#fff' : '#1e88e5'} />
          </Box>
          <Typography variant="h3" sx={{ fontWeight: 800 }}>Meeting Schedule</Typography>
        </Stack>
      }
      secondary={
        <BOSTableToolbar
          onRefresh={fetchData}
          onNew={handleAdd}
          newTooltip={shortcutTooltip('Create New Schedule', 'Ctrl + N')}
          hasWritePermission={perms.write}
          exportData={filteredRows}
          
          exportFilename="Meeting_Schedule"
          hasExportPermission={perms.export}
          onAmendment={() => {
            if (resolvedRows.length > 0) handleAmendmentClick(resolvedRows[0]);
            else dispatch(openSnackbar({ open: true, message: 'Please select a schedule to amend', variant: 'alert', severity: 'warning' }));
          }}
          amendmentLabel="+ Amendment"
          amendmentColor="warning"
          amendmentVariant="outlined"
          amendmentIcon={<IconGitBranch size={18} />}
          amendmentTooltip="Create Amendment"
          amendmentSx={{ borderRadius: '12px', fontWeight: 700 }}
         columns={columns} />
      }
    >
      <BOSDataTable
        columns={columns}
        rows={filteredRows}
        page={page}
        size={size}
        loading={loading}
        onPageChange={setPage}
        onSizeChange={(s) => { setSize(s); setPage(0); }}
        onDoubleClickRow={handleEdit}
        onEditRow={perms.write ? handleEdit : undefined}
        onDeleteRow={perms.delete ? handleDeleteClick : undefined}
        renderCell={renderCell}
        id="meeting-schedule-table"
      />



      <ConfirmDeleteDialog
        open={deleteDialogOpen}
        onClose={() => setDeleteDialogOpen(false)}
        onConfirm={handleDeleteConfirm}
        title="Delete Meeting Schedule"
        message="Are you sure you want to delete this schedule? This action cannot be undone."
        itemName={deleteTarget?.scheduleNo}
      />

      {/* Amendment Confirmation Dialog */}
      <Dialog open={amendDialogOpen} onClose={() => setAmendDialogOpen(false)} maxWidth="xs" fullWidth>
        <DialogTitle>Amendment Confirmation</DialogTitle>
        <DialogContent>
          <Typography>Are you sure want to Amendment this Record?</Typography>
          {selectedForAmend && (
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
              Schedule: <strong>{selectedForAmend.scheduleNo}</strong>
            </Typography>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setAmendDialogOpen(false)}>No</Button>
          <Button variant="contained" color="warning" onClick={handleAmendConfirm}>Yes</Button>
        </DialogActions>
      </Dialog>
    </MainCard>
  );
}
